  /**
   * @method
   * @name apex#fetchTime
   * @description fetches the current integer timestamp in milliseconds from the
   * exchange server
   * @see
   * https://api-docs.omni.apex.exchange/#publicapi-v3-for-omni-get-system-time-v3
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {int} the current integer timestamp in milliseconds from the
   * exchange server
   */
  std::shared_future<ccxt::any>
  fetchTime(ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        ccxt::any response =
                            awaitValue(this->publicGetV3Time(params));
                        ccxt::any data = this->safeDict(
                            response, std::string("data"), ccxt::dict{});
                        //
                        // {
                        //    "data": {
                        //    "time": 1738837534454
                        //     }
                        // }
                        return this->safeInteger(data, std::string("time"));
                      })
        .share();
  }

  ccxt::any parseBalance(ccxt::any response) override {
    //
    // {
    //     "totalEquityValue": "100.000000",
    //     "availableBalance": "100.000000",
    //     "initialMargin": "100.000000",
    //     "maintenanceMargin": "100.000000",
    //     "symbolToOraclePrice": {
    //     "BTC-USDC": {
    //         "oraclePrice": "20000",
    //             "createdTime": 124566
    //     }
    // }
    // }
    //
    ccxt::any timestamp = this->milliseconds();
    ccxt::any result = ccxt::dict{
        {std::string("info"), response},
        {std::string("timestamp"), timestamp},
        {std::string("datetime"), this->iso8601(timestamp)},
    };
    ccxt::any code = std::string("USDT");
    ccxt::any account = this->account();
    ::setValue(account, std::string("free"),
               this->safeString(response, std::string("availableBalance")));
    ::setValue(account, std::string("total"),
               this->safeString(response, std::string("totalEquityValue")));
    ::setValue(result, code, account);
    return this->safeBalance(result);
  }

  /**
   * @method
   * @name apex#fetchBalance
   * @description query for account info
   * @see
   * https://api-docs.omni.apex.exchange/#privateapi-v3-for-omni-get-retrieve-user-account-balance
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [balance structure]{@link
   * https://docs.ccxt.com/?id=balance-structure}
   */
  std::shared_future<ccxt::any>
  fetchBalance(ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        ccxt::any response = awaitValue(
                            this->privateGetV3AccountBalance(params));
                        ccxt::any data = this->safeDict(
                            response, std::string("data"), ccxt::dict{});
                        return this->parseBalance(data);
                      })
        .share();
  }

  ccxt::any parseAccount(ccxt::any account) override {
    ccxt::any accountId =
        this->safeString(account, std::string("id"), std::string("0"));
    return ccxt::dict{
        {std::string("id"), accountId},
        {std::string("type"), ccxt::any{}},
        {std::string("code"), ccxt::any{}},
        {std::string("info"), account},
    };
  }

  /**
   * @method
   * @name apex#fetchAccount
   * @description query for balance and get the amount of funds available for
   * trading or funds locked in orders
   * @see
   * https://api-docs.omni.apex.exchange/#privateapi-v3-for-omni-get-retrieve-user-account-data
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [balance structure]{@link
   * https://docs.ccxt.com/?id=balance-structure}
   */
  virtual std::shared_future<ccxt::any>
  fetchAccount(ccxt::any params = ccxt::dict{}) {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        ccxt::any response =
                            awaitValue(this->privateGetV3Account(params));
                        ccxt::any data = this->safeDict(
                            response, std::string("data"), ccxt::dict{});
                        return this->parseAccount(data);
                      })
        .share();
  }

