  ccxt::any parseMarket(ccxt::any market) override {
    ccxt::any id = this->safeString(market, std::string("symbol"));
    ccxt::any id2 = this->safeString(market, std::string("crossSymbolName"));
    ccxt::any quoteId = this->safeString(market, std::string("l2PairId"));
    ccxt::any baseId = this->safeString(market, std::string("baseTokenId"));
    ccxt::any quote = this->safeString(market, std::string("settleAssetId"));
    ccxt::any base = this->safeCurrencyCode(baseId);
    ccxt::any settleId = this->safeString(market, std::string("settleAssetId"));
    ccxt::any settle = this->safeCurrencyCode(settleId);
    ccxt::any symbol =
        add(add(add(add(baseId, std::string("/")), quote), std::string(":")),
            settle);
    ccxt::any expiry = 0;
    ccxt::any takerFee = this->parseNumber(std::string("0.0002"));
    ccxt::any makerFee = this->parseNumber(std::string("0.0005"));
    return this->safeMarketStructure(ccxt::dict{
        {std::string("id"), id},
        {std::string("id2"), id2},
        {std::string("symbol"), symbol},
        {std::string("base"), base},
        {std::string("quote"), quote},
        {std::string("settle"), settle},
        {std::string("baseId"), baseId},
        {std::string("quoteId"), quoteId},
        {std::string("settleId"), settleId},
        {std::string("type"), std::string("swap")},
        {std::string("spot"), false},
        {std::string("margin"), ccxt::any{}},
        {std::string("swap"), true},
        {std::string("future"), false},
        {std::string("option"), false},
        {std::string("active"),
         this->safeBool(market, std::string("enableTrade"))},
        {std::string("contract"), true},
        {std::string("linear"), true},
        {std::string("inverse"), false},
        {std::string("taker"), takerFee},
        {std::string("maker"), makerFee},
        {std::string("contractSize"),
         this->safeNumber(market, std::string("minOrderSize"))},
        {std::string("expiry"),
         (isTrue((isEqual(expiry, 0))) ? ccxt::any(ccxt::any{})
                                       : ccxt::any(expiry))},
        {std::string("expiryDatetime"),
         (isTrue((isEqual(expiry, 0))) ? ccxt::any(ccxt::any{})
                                       : ccxt::any(this->iso8601(expiry)))},
        {std::string("strike"), ccxt::any{}},
        {std::string("optionType"), ccxt::any{}},
        {std::string("precision"),
         ccxt::dict{
             {std::string("amount"),
              this->safeNumber(market, std::string("stepSize"))},
             {std::string("price"),
              this->safeNumber(market, std::string("tickSize"))},
         }},
        {std::string("limits"),
         ccxt::dict{
             {std::string("leverage"),
              ccxt::dict{
                  {std::string("min"),
                   this->safeNumber(market, std::string("displayMinLeverage"))},
                  {std::string("max"),
                   this->safeNumber(market, std::string("displayMaxLeverage"))},
              }},
             {std::string("amount"),
              ccxt::dict{
                  {std::string("min"),
                   this->safeNumber(market, std::string("minOrderSize"))},
                  {std::string("max"),
                   this->safeNumber(market, std::string("maxOrderSize"))},
              }},
             {std::string("price"),
              ccxt::dict{
                  {std::string("min"), ccxt::any{}},
                  {std::string("max"), ccxt::any{}},
              }},
             {std::string("cost"),
              ccxt::dict{
                  {std::string("min"), ccxt::any{}},
                  {std::string("max"), ccxt::any{}},
              }},
         }},
        {std::string("created"), ccxt::any{}},
        {std::string("info"), market},
    });
  }

  ccxt::any parseTicker(ccxt::any ticker,
                        ccxt::any market = ccxt::any{}) override {
    //
    // {
    //     "symbol": "BTCUSDT",
    //     "price24hPcnt": "0.450141",
    //     "lastPrice": "43511.50",
    //     "highPrice24h": "43513.50",
    //     "lowPrice24h": "29996.00",
    //     "markPrice": "43513.50",
    //     "indexPrice": "40828.94",
    //     "openInterest": "2036854775808",
    //     "turnover24h": "5626085.23749999",
    //     "volume24h": "169.317",
    //     "fundingRate": "0",
    //     "predictedFundingRate": "0",
    //     "nextFundingTime": "10:00:00",
    //     "tradeCount": 100
    // }
    //
    ccxt::any timestamp = this->milliseconds();
    ccxt::any marketId = this->safeString(ticker, std::string("symbol"));
    market = this->safeMarket(marketId, market);
    ccxt::any symbol = this->safeSymbol(marketId, market);
    ccxt::any last = this->safeString(ticker, std::string("lastPrice"));
    ccxt::any percentage =
        this->safeString(ticker, std::string("price24hPcnt"));
    ccxt::any quoteVolume =
        this->safeString(ticker, std::string("turnover24h"));
    ccxt::any baseVolume = this->safeString(ticker, std::string("volume24h"));
    ccxt::any high = this->safeString(ticker, std::string("highPrice24h"));
    ccxt::any low = this->safeString(ticker, std::string("lowPrice24h"));
    return this->safeTicker(
        ccxt::dict{
            {std::string("symbol"), symbol},
            {std::string("timestamp"), timestamp},
            {std::string("datetime"), this->iso8601(timestamp)},
            {std::string("high"), high},
            {std::string("low"), low},
            {std::string("bid"), ccxt::any{}},
            {std::string("bidVolume"), ccxt::any{}},
            {std::string("ask"), ccxt::any{}},
            {std::string("askVolume"), ccxt::any{}},
            {std::string("vwap"), ccxt::any{}},
            {std::string("open"), ccxt::any{}},
            {std::string("close"), last},
            {std::string("last"), last},
            {std::string("previousClose"), ccxt::any{}},
            {std::string("change"), ccxt::any{}},
            {std::string("percentage"), percentage},
            {std::string("average"), ccxt::any{}},
            {std::string("baseVolume"), baseVolume},
            {std::string("quoteVolume"), quoteVolume},
            {std::string("markPrice"),
             this->safeString(ticker, std::string("markPrice"))},
            {std::string("indexPrice"),
             this->safeString(ticker, std::string("indexPrice"))},
            {std::string("info"), ticker},
        },
        market);
  }

  /**
   * @method
   * @name apex#fetchTicker
   * @description fetches a price ticker, a statistical calculation with the
   * information calculated over the past 24 hours for a specific market
   * @see
   * https://api-docs.omni.apex.exchange/#publicapi-v3-for-omni-get-ticker-data-v3
   * @param {string} symbol unified symbol of the market to fetch the ticker for
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [ticker structure]{@link
   * https://docs.ccxt.com/?id=ticker-structure}
   */
  std::shared_future<ccxt::any>
  fetchTicker(ccxt::any symbol, ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        ccxt::any market = this->market(symbol);
                        ccxt::any request = ccxt::dict{
                            {std::string("symbol"),
                             this->safeString(market, std::string("id2"))},
                        };
                        ccxt::any response = awaitValue(this->publicGetV3Ticker(
                            this->extend(request, params)));
                        ccxt::any tickers = this->safeList(
                            response, std::string("data"), ccxt::list{});
                        ccxt::any rawTicker =
                            this->safeDict(tickers, 0, ccxt::dict{});
                        return this->parseTicker(rawTicker, market);
                      })
        .share();
  }

  /**
   * @method
   * @name apex#fetchTickers
   * @description fetches a price ticker, a statistical calculation with the
   * information calculated over the past 24 hours for a specific market
   * @see
   * https://api-docs.omni.apex.exchange/#publicapi-v3-for-omni-get-ticker-data-v3
   * @param {string} symbols unified symbol of the market to fetch the ticker
   * for
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [ticker structure]{@link
   * https://docs.ccxt.com/?id=ticker-structure}
   */
  std::shared_future<ccxt::any>
  fetchTickers(ccxt::any symbols = ccxt::any{},
               ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        ccxt::any response = awaitValue(
                            this->publicGetV3DataAllTickerInfo(params));
                        ccxt::any tickers = this->safeList(
                            response, std::string("data"), ccxt::list{});
                        return this->parseTickers(tickers, symbols);
                      })
        .share();
  }

  /**
   * @method
   * @name apex#fetchOHLCV
   * @description fetches historical candlestick data containing the open, high,
   * low, and close price, and the volume of a market
   * @see
   * https://api-docs.omni.apex.exchange/#publicapi-v3-for-omni-get-candlestick-chart-data-v3
   * @param {string} symbol unified symbol of the market to fetch OHLCV data for
   * @param {string} timeframe the length of time each candle represents
   * @param {int} [since] timestamp in ms of the earliest candle to fetch
   * @param {int} [limit] the maximum amount of candles to fetch
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.until] timestamp in ms of the latest candle to fetch
   * @returns {int[][]} A list of candles ordered as timestamp, open, high, low,
   * close, volume
   */
  std::shared_future<ccxt::any>
  fetchOHLCV(ccxt::any symbol, ccxt::any timeframe = std::string("1m"),
             ccxt::any since = ccxt::any{}, ccxt::any limit = ccxt::any{},
             ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any market = this->market(symbol);
                 ccxt::any request = ccxt::dict{
                     {std::string("interval"),
                      this->safeString(this->timeframes, timeframe, timeframe)},
                     {std::string("symbol"),
                      this->safeString(market, std::string("id2"))},
                 };
                 if (isTrue(isEqual(limit, ccxt::any{}))) {
                   limit = 200; // default is 200 when requested with `since`
                 }
                 ::setValue(request, std::string("limit"),
                            limit); // max 200, default 200
                 ccxt::any requestparamsVariable = this->handleUntilOption(
                     std::string("end"), request, params, 0.001);
                 request = ::getValue(requestparamsVariable, 0);
                 params = ::getValue(requestparamsVariable, 1);
                 if (isTrue(!isEqual(since, ccxt::any{}))) {
                   ::setValue(request, std::string("start"),
                              mathFloor(divide(since, 1000)));
                 }
                 ccxt::any response = awaitValue(
                     this->publicGetV3Klines(this->extend(request, params)));
                 ccxt::any data = this->safeDict(response, std::string("data"),
                                                 ccxt::dict{});
                 ccxt::any OHLCVs = this->safeList(
                     data, this->safeString(market, std::string("id2")),
                     ccxt::list{});
                 return this->parseOHLCVs(OHLCVs, market, timeframe, since,
                                          limit);
               })
        .share();
  }

  ccxt::any parseOHLCV(ccxt::any ohlcv,
                       ccxt::any market = ccxt::any{}) override {
    //
    //  {
    //     "start": 1647511440000,
    //     "symbol": "BTC-USD",
    //     "interval": "1",
    //     "low": "40000",
    //     "high": "45000",
    //     "open": "45000",
    //     "close": "40000",
    //     "volume": "1.002",
    //     "turnover": "3"
    //  }
    //  {"s":"BTCUSDT","i":"1","t":1741265880000,"c":"90235","h":"90235","l":"90156","o":"90156","v":"0.052","tr":"4690.4466"}
    //
    return ccxt::list{
        this->safeInteger2(ohlcv, std::string("start"), std::string("t")),
        this->safeNumber2(ohlcv, std::string("open"), std::string("o")),
        this->safeNumber2(ohlcv, std::string("high"), std::string("h")),
        this->safeNumber2(ohlcv, std::string("low"), std::string("l")),
        this->safeNumber2(ohlcv, std::string("close"), std::string("c")),
        this->safeNumber2(ohlcv, std::string("volume"), std::string("v"))};
  }

  /**
   * @method
   * @name apex#fetchOrderBook
   * @description fetches information on open orders with bid (buy) and ask
   * (sell) prices, volumes and other data
   * @see
   * https://api-docs.omni.apex.exchange/#publicapi-v3-for-omni-get-market-depth-v3
   * @param {string} symbol unified symbol of the market to fetch the order book
   * for
   * @param {int} [limit] the maximum amount of order book entries to return
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} an [order book structure]{@link
   * https://docs.ccxt.com/?id=order-book-structure}
   */
  std::shared_future<ccxt::any>
  fetchOrderBook(ccxt::any symbol, ccxt::any limit = ccxt::any{},
                 ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any market = this->market(symbol);
                 ccxt::any request = ccxt::dict{
                     {std::string("symbol"),
                      this->safeString(market, std::string("id2"))},
                 };
                 if (isTrue(isEqual(limit, ccxt::any{}))) {
                   limit = 100; // default is 200 when requested with `since`
                 }
                 ::setValue(request, std::string("limit"),
                            limit); // max 100, default 100
                 ccxt::any response = awaitValue(
                     this->publicGetV3Depth(this->extend(request, params)));
                 //
                 // {
                 //     "a": [
                 //     [
                 //         "96576.3",
                 //         "0.399"
                 //     ],
                 //     [
                 //         "96577.6",
                 //         "0.106"
                 //     ]
                 // ],
                 //     "b": [
                 //     [
                 //         "96565.2",
                 //         "0.131"
                 //     ],
                 //     [
                 //         "96565.1",
                 //         "0.038"
                 //     ]
                 // ],
                 //     "s": "BTCUSDT",
                 //     "u": 18665465
                 // }
                 //
                 ccxt::any data = this->safeDict(response, std::string("data"),
                                                 ccxt::dict{});
                 ccxt::any timestamp = this->milliseconds();
                 ccxt::any orderbook = this->parseOrderBook(
                     data, ::getValue(market, std::string("symbol")), timestamp,
                     std::string("b"), std::string("a"));
                 ::setValue(orderbook, std::string("nonce"),
                            this->safeInteger(data, std::string("u")));
                 return orderbook;
               })
        .share();
  }

  /**
   * @method
   * @name apex#fetchTrades
   * @description get the list of most recent trades for a particular symbol
   * @see
   * https://api-docs.omni.apex.exchange/#publicapi-v3-for-omni-get-newest-trading-data-v3
   * @param {string} symbol unified symbol of the market to fetch trades for
   * @param {int} [since] timestamp in ms of the earliest trade to fetch
   * @param {int} [limit] the maximum amount of trades to fetch
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.until] the latest time in ms to fetch trades for
   * @param {boolean} [params.paginate] default false, when true will
   * automatically paginate by calling this endpoint multiple times
   * @returns {Trade[]} a list of [trade structures]{@link
   * https://docs.ccxt.com/?id=public-trades}
   */
  std::shared_future<ccxt::any>
  fetchTrades(ccxt::any symbol, ccxt::any since = ccxt::any{},
              ccxt::any limit = ccxt::any{},
              ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        ccxt::any market = this->market(symbol);
                        ccxt::any request = ccxt::dict{
                            {std::string("symbol"),
                             this->safeString(market, std::string("id2"))},
                        };
                        if (isTrue(isEqual(limit, ccxt::any{}))) {
                          limit = 500; // default is 50
                        }
                        ::setValue(request, std::string("limit"), limit);
                        ccxt::any response = awaitValue(this->publicGetV3Trades(
                            this->extend(request, params)));
                        //
                        // [
                        //  {
                        //      "i": "993f7f85-9215-5723-9078-2186ae140847",
                        //      "p": "96534.3",
                        //      "S": "Sell",
                        //      "v": "0.261",
                        //      "s": "BTCUSDT",
                        //      "T": 1739118072710
                        //  },
                        //  {
                        //      "i": "c947c9cf-8c18-5784-89c3-91bdf86ddde8",
                        //      "p": "96513.5",
                        //      "S": "Sell",
                        //      "v": "0.042",
                        //      "s": "BTCUSDT",
                        //      "T": 1739118075944
                        //  }
                        //  ]
                        //
                        ccxt::any trades = this->safeList(
                            response, std::string("data"), ccxt::list{});
                        return this->parseTrades(trades, market, since, limit);
                      })
        .share();
  }

  ccxt::any parseTrade(ccxt::any trade,
                       ccxt::any market = ccxt::any{}) override {
    //
    // [
    //  {
    //      "i": "993f7f85-9215-5723-9078-2186ae140847",
    //      "p": "96534.3",
    //      "S": "Sell",
    //      "v": "0.261",
    //      "s": "BTCUSDT",
    //      "T": 1739118072710
    //  }
    //  ]
    //
    ccxt::any marketId =
        this->safeString2(trade, std::string("s"), std::string("symbol"));
    market = this->safeMarket(marketId, market);
    ccxt::any id =
        this->safeString2(trade, std::string("i"), std::string("id"));
    ccxt::any timestamp =
        this->safeIntegerN(trade, ccxt::list{std::string("t"), std::string("T"),
                                             std::string("createdAt")});
    ccxt::any priceString =
        this->safeString2(trade, std::string("p"), std::string("price"));
    ccxt::any amountString =
        this->safeString2(trade, std::string("v"), std::string("size"));
    ccxt::any side =
        this->safeStringLower2(trade, std::string("S"), std::string("side"));
    ccxt::any type = this->safeString(trade, std::string("type"));
    ccxt::any fee = this->safeString(trade, std::string("fee"));
    return this->safeTrade(
        ccxt::dict{
            {std::string("info"), trade},
            {std::string("id"), id},
            {std::string("order"), ccxt::any{}},
            {std::string("timestamp"), timestamp},
            {std::string("datetime"), this->iso8601(timestamp)},
            {std::string("symbol"), ::getValue(market, std::string("symbol"))},
            {std::string("type"), type},
            {std::string("takerOrMaker"), ccxt::any{}},
            {std::string("side"), side},
            {std::string("price"), priceString},
            {std::string("amount"), amountString},
            {std::string("cost"), ccxt::any{}},
            {std::string("fee"), fee},
        },
        market);
  }

  /**
   * @method
   * @name apex#fetchOpenInterest
   * @description retrieves the open interest of a contract trading pair
   * @see
   * https://api-docs.omni.apex.exchange/#publicapi-v3-for-omni-get-ticker-data-v3
   * @param {string} symbol unified CCXT market symbol
   * @param {object} [params] exchange specific parameters
   * @returns {object} an open interest structure{@link
   * https://docs.ccxt.com/?id=open-interest-structure}
   */
  std::shared_future<ccxt::any>
  fetchOpenInterest(ccxt::any symbol,
                    ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        ccxt::any market = this->market(symbol);
                        ccxt::any request = ccxt::dict{
                            {std::string("symbol"),
                             this->safeString(market, std::string("id2"))},
                        };
                        ccxt::any response = awaitValue(this->publicGetV3Ticker(
                            this->extend(request, params)));
                        ccxt::any tickers = this->safeList(
                            response, std::string("data"), ccxt::list{});
                        ccxt::any rawTicker =
                            this->safeDict(tickers, 0, ccxt::dict{});
                        return this->parseOpenInterest(rawTicker, market);
                      })
        .share();
  }

